import unittest

from solucao import ultimo
from solucao import penultimo


class TestPosicaoNegativa(unittest.TestCase):
    def test_devolve_o_ultimo(self):
        """ultimo devolve o ultimo item da lista"""
        self.assertEqual(ultimo([["ana", 10], ["bia", 20], ["caio", 30]]), ["caio", 30])

    def test_ultimo_de_lista_de_um(self):
        """ultimo de uma lista de um item devolve esse item"""
        self.assertEqual(ultimo([["so", 1]]), ["so", 1])

    def test_devolve_o_penultimo(self):
        """penultimo devolve o penultimo item da lista"""
        self.assertEqual(penultimo([["ana", 10], ["bia", 20], ["caio", 30]]), ["bia", 20])

